using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidNativeValidationStatusFileStore{private readonly string _path;public AndroidNativeValidationStatusFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(AndroidNativeValidationStatus value){if(value.LiveTradingEnabled)throw new InvalidOperationException("Android validation state cannot grant live authority.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public AndroidNativeValidationStatus Load(){var v=JsonSerializer.Deserialize<AndroidNativeValidationStatus>(File.ReadAllText(_path))??throw new InvalidOperationException("Android validation status JSON is invalid.");if(v.LiveTradingEnabled)throw new InvalidOperationException("Persisted Android validation state grants live authority.");return v;}}
